def find_c_for_k2_1():
    for c in range(-100, 1000):
        # Q(a) = a^3 + (c-1)a^2 - ca + 1
        # Check if Q(a) is a square only for a=0, 1
        possible = True
        for a in range(-100, 100):
            if a == 0 or a == 1:
                continue
            val = a**3 + (c-1)*a**2 - c*a + 1
            if is_square(val):
                possible = False
                break
        if possible:
            return c
    return None

