def check_zero_possible():
    # P(2024)=0, P(2025)=1. Q(a) = a^3 + c2*a^2 + (1-1-c2)*a = a^3 + c2*a^2 - c2*a
    for c2 in range(-1000, 1000):
        possible = True
        # We only need to check a in a certain range.
        # For a > 0, Q(a) = a(a^2 + c2*a - c2). 
        # If c2 is large, Q(a) is between (a+c2/2-1)^2 and (a+c2/2)^2.
        # Let's just check a in a range.
        for a in range(-1000, 1000):
            if a == 0 or a == 1:
                continue
            val = a**3 + c2*a**2 - c2*a
            if is_square(val):
                possible = False
                break
        if possible:
            return c2
    return None

print(f"c2 for P(2024)=0, P(2025)=1: {check_zero_possible()}")
